 56	// already-opened handle. Keeping the lexical spelling here is not just
 57	// cosmetic: NTFS can resolve Unicode case aliases and DOS 8.3 names that Go's
 58	// generic Unicode folding does not model, so a pointer and a directory listing
 59	// can name the same git directory with keys that never compare equal.
 60	//
 61	// Asking the handle avoids a second pathname walk after the rooted, same-volume
 62	// open. In particular, filepath.EvalSymlinks here would reintroduce a race in
 63	// which a repository replaces a checked component with a UNC redirect before
 64	// the canonicalization walk.
 65	func windowsOpenedPath(file *os.File) (string, error) {
 66		const maxWindowsPathUTF16 = 32_768
 67		buffer := make([]uint16, 512)
 68		for {
 69			n, _, callErr := getFinalPathNameByHandle.Call(
 70				file.Fd(),
 71				uintptr(unsafe.Pointer(&buffer[0])),
 72				uintptr(len(buffer)),
 73				0,
 74			)
 75			if n == 0 {
 76				if callErr != nil && callErr != syscall.Errno(0) {
 77					return "", callErr
 78				}
 79				return "", fmt.Errorf("GetFinalPathNameByHandleW returned an empty path")
 80			}
 81			if n >= uintptr(len(buffer)) {
 82				if n >= maxWindowsPathUTF16 {
 83					return "", fmt.Errorf("GetFinalPathNameByHandleW path exceeds %d UTF-16 code units", maxWindowsPathUTF16-1)
 84				}
 85				buffer = make([]uint16, int(n)+1)
 86				continue
 87			}
 88			resolved := syscall.UTF16ToString(buffer[:n])
 89			switch {
 90			case strings.HasPrefix(resolved, `\\?\UNC\`):
 91				resolved = `\\` + resolved[len(`\\?\UNC\`):]
 92			case strings.HasPrefix(resolved, `\\?\`):
 93				resolved = resolved[len(`\\?\`):]
 94			default:
