 19	func newPathTraversalAnchor(baseAbs, value string) (pathTraversalAnchor, string, error) {
 20		if !sameVolume(value, baseAbs) {
 21			return pathTraversalAnchor{}, "", errSymlinkChainOffVolume
 22		}
 23		volume := filepath.VolumeName(baseAbs)
 24		root := string(filepath.Separator)
 25		if volume != "" {
 26			root = volume + string(filepath.Separator)
 27		}
