 33		closeErr := rootFile.Close()
 34		if physicalErr != nil {
 35			return pathTraversalAnchor{}, "", physicalErr
 36		}
 37		if closeErr != nil {
 38			return pathTraversalAnchor{}, "", closeErr
 39		}
 40		return pathTraversalAnchor{root: root, physicalRoot: physicalRoot}, value, nil
 41	}
 42	
 43	func (a pathTraversalAnchor) components(value string) ([]string, bool) {
 44		if !sameVolume(value, a.root) {
 45			return nil, false
 46		}
 47		rest := value[len(filepath.VolumeName(value)):]
 48		return splitNativePathComponents(rest), true
 49	}
